/* 故事工作台：每次只显示一个步骤，原文和已发布资产分开保存。 */
window.mountScriptStudio=function(host,options={}){
const M=ScriptStudio,E=Cimora.E,KEY='cimora-script-studio-v1',steps=['创作起点','策划 / 范围','故事稿','剧情分析','分集大纲','分集内容','保存与使用'];let state=options.load(),p=options.newIntent?null:state.projects.find(x=>x.id===state.active),message='',busy=false,alive=true,rewriteOpen=false,storyReplace=false;
if(!p)p=M.create(); // 首次操作前仅驻留内存，不写入空工程。
const $=s=>host.querySelector(s),B=(text,action,primary=false,extra='')=>`<button class="cm-button ${primary?'primary':'ghost'}" data-ss="${action}" ${extra}>${text}</button>`;
function save(){if(!alive)return false;if(!state.projects.some(x=>x.id===p.id))state.projects.push(p);state.active=p.id;const ok=options.save(state);host.querySelectorAll('[data-pref-summary]').forEach(el=>el.textContent=p.settings[el.dataset.prefSummary]||(el.dataset.prefSummary==='audience'?'不限':'未设置'));const status=$('#ss-save');if(status)status.textContent=ok?'已自动保存 · 刷新可继续':'未保存到本机，请立即导出备份';const url='#/app/script?project='+encodeURIComponent(p.id);if(location.hash!==url)history.replaceState(null,'',url);return ok;}
function at(path){return path.split('.').reduce((o,k)=>o?.[k],p);}
function field(path,label,rows=3,extra=''){return `<label>${label}<textarea data-p="${path}" rows="${rows}" ${extra}>${E(at(path)||'')}</textarea></label>`;}
function input(path,label,placeholder=''){return `<label>${label}<input data-p="${path}" value="${E(at(path)||'')}"${placeholder?` placeholder="${E(placeholder)}"`:''}></label>`;}
function select(path,label,choices){return `<label>${label}<select data-p="${path}">${choices.map(([v,t])=>`<option value="${v}" ${at(path)===v?'selected':''}>${t}</option>`).join('')}</select></label>`;}
const help=t=>`<p class="ss-help">${t}</p>`,notice=t=>`<p class="ss-notice">${t}</p>`;
function details(){return `<details class="ss-context"><summary>设定与相关来源 · 按需查看</summary><p>${E(p.characters.map(c=>c.name+(c.aliases?'（'+c.aliases+'）':'')+'：'+c.identity+'；'+c.relation).join('\n')||'尚未确认人物，前往剧情分析添加。')}</p><p>${E(p.facts||'尚未确认世界与不可改事实')}</p><p>来源：${E(p.sourceName)}；${p.scope==='full'?'全文':p.scope==='chapter'?'所选章节':'片段'} · 原文完整保留</p>${p.outline.length?`<p>当前集大纲：${E(p.outline.find(e=>e.id===p.selectedEpisode)?.events||'尚未选择')}</p><p>前集结束状态：${E(previous()?.state||previous()?.ending||'无前集 / 待确认')}</p><p>伏笔：${E(previous()?.foreshadow||p.analysis.foreshadow||'待确认')}</p>`:''}<details><summary>完整原文 · ${M.count(p.original)}字</summary><pre>${E(p.original)}</pre></details></details>`;}
function previous(){let i=p.outline.findIndex(e=>e.id===p.selectedEpisode);return p.outline[i-1];}
function ideaMode(){return p.origin==='idea'&&p.stage<2&&(!p.directions.length||!!p.ideaDesk);}
const prefUI={open:false,genre:'',style:'',more:false};
const presets={genre:[['romance','爱情'],['mystery','悬疑'],['adventure','冒险'],['fantasy','奇幻'],['scifi','科幻'],['horror','恐怖'],['comedy','喜剧'],['drama','剧情']],style:[['warm','温暖'],['humorous','幽默'],['tense','紧张'],['dark','黑暗'],['romantic','浪漫'],['absurd','荒诞'],['realistic','写实'],['poetic','诗意']]};
function prefStore(write=false){if(write){state.preferenceUI??={};return state.preferenceUI[p.id]??={};}return state.preferenceUI?.[p.id]||{};}
function preferences(){const labels={genre:'故事类型',core:'背景设定',style:'情绪与风格',audience:'目标读者'},key=prefUI.active;
const tags=k=>{const v=M.preferenceState(p,prefStore(),k);return `${v.legacy?`<label>自定义内容<input data-pref-legacy="${k}" value="${E(v.legacy)}"></label>`:''}<div class="ss-pref-tags">${v.tags.map(t=>B(E(t.label)+' ×','pref-toggle',true,`data-key="${k}" data-token="${E(t.id)}" data-label="${E(t.label)}" aria-label="移除${E(t.label)}"`)).join('')}</div>${CimoraSearchField.render(`<input data-pref-search="${k}" value="${E(prefUI[k])}" placeholder="搜索或自定义，按 Enter 添加" aria-label="搜索或自定义${labels[k]}">`)}<div class="ss-pref-options" data-pref-options="${k}">${presets[k].map(([id,t])=>`<span data-pref-option="${t}" ${!t.includes(prefUI[k])?'hidden':''}>${B(t,'pref-toggle',v.tags.some(x=>x.id===id),`data-key="${k}" data-token="${id}" data-label="${t}" aria-pressed="${v.tags.some(x=>x.id===id)}"`)}</span>`).join('')}</div>`;};
const audience=()=>`<label>目标读者<select id="ss-pref-audience">${[['','不限'],['children','儿童'],['teen','青少年'],['adult','成人'],['custom','自定义']].map(([id,t])=>`<option value="${id}" ${(!prefUI.audienceCustom&&p.settings.audience===({children:'儿童',teen:'青少年',adult:'成人'}[id]||'')&&id!=='custom'||id==='custom'&&(prefUI.audienceCustom||p.settings.audience&&!['儿童','青少年','成人'].includes(p.settings.audience)))?'selected':''}>${t}</option>`).join('')}</select></label>${p.settings.audience&&!['儿童','青少年','成人'].includes(p.settings.audience)||prefUI.audienceCustom?input('settings.audience','自定义读者','输入目标读者'):''}`;
return `<div id="ss-preferences"><div class="ss-pref-summary">${Object.entries(labels).map(([k,t])=>`<button class="ss-pref-entry" data-ss="pref-open" data-key="${k}" aria-expanded="${key===k}"><span>${t}</span><small data-pref-summary="${k}">${E(p.settings[k]||(k==='audience'?'不限':'未设置'))}</small></button>`).join('')}</div>${key?`<section class="ss-pref-panel" aria-label="编辑${labels[key]}"><header><strong>${labels[key]}</strong>${B('完成','pref-close')}</header>${key==='genre'||key==='style'?tags(key):key==='audience'?audience():`${input('settings.core','背景设定','自由描述背景或特别设定')}<div class="ss-pref-options">${['过去','当代','未来','现实','架空'].map(t=>B(t,'pref-core',false,`data-label="${t}"`)).join('')}</div>`}</section>`:''}</div>`;
}
function ideaWorkspace(){const d=p.ideaDesk||{messages:[],draft:'',target:'synopsis',selected:-1,plans:[]},plan=d.plans[d.selected];
const editor=(key,label,rows=2)=>`<label>${label}<textarea data-plan="${key}" rows="${rows}">${E(plan[key]||'')}</textarea></label>`;
return `<div class="ss-idea-layout"><section class="ss-idea-chat ${d.plans.length?'has-plans':''}" aria-label="对话完善"><header><span class="cm-kicker">01 / DEVELOP</span><h2>一起把灵感说清楚</h2><p>左边说想法，右边选择并打磨故事方案。</p></header><div class="ss-idea-simulation">本机模拟 · 要求原句补充，待你融合；未接模型。</div><p id="ss-message" role="status">${E(message)}</p>${!d.plans.length?`${field('original','一句灵感 / 故事梗概',4)}${B('从这句灵感开始 →','idea-start',true)}${preferences()}<a class="ss-idea-import" href="#" data-ss="origin-import">已有原文？上传 / 粘贴 →</a>`:`<div class="ss-idea-messages" aria-label="完善记录">${d.messages.map(m=>`<article class="ss-idea-message ${m.role}"><strong>${m.role==='user'?'你':'策划助手 · 本机模拟'}</strong><p>${E(m.text)}</p></article>`).join('')}</div><div class="ss-idea-composer"><strong>${plan?'正在完善方案'+(d.selected+1)+' · '+E(plan.title):'先在右侧选一个方向'}</strong><label>继续说说你的要求<textarea id="ss-idea-message" rows="2" placeholder="例如：让主角主动揭开秘密，但保留开放结局">${E(d.draft)}</textarea></label>${B('完善方案 →','idea-refine',true,plan?'':'disabled')}</div>`}</section><section class="ss-idea-plan" aria-label="故事方案"><header><span class="cm-kicker">02 / STORY PLAN</span><h2>你的故事方案</h2><p>先选方向，再展开细节；每一项都可以直接编辑。</p></header>${!d.plans.length?`<div class="ss-idea-empty"><span>✧</span><h3>一个想法，就可以开始</h3><p>提交左侧灵感后，这里会出现三个简短方向。<br>选中以后，再一起完善人物、世界与梗概。</p>${input('title','故事名称（可选）')}</div>`:`<div class="ss-idea-cards">${d.plans.map((x,i)=>`<article class="ss-idea-direction ${i===d.selected?'selected':''}"><span>方案 ${i+1}</span><h3>${E(x.title)}</h3><p><b>看点</b> ${E(x.hook)}</p><p><b>核心冲突</b> ${E(x.conflict.length>105?x.conflict.slice(0,105)+'…':x.conflict)}</p>${B(i===d.selected?'正在完善':'选择这个方向','idea-choose',i===d.selected,`data-index="${i}"`)}</article>`).join('')}</div>${plan?`<div class="ss-idea-editor"><div class="ss-idea-editor-heading"><h3>方案 ${d.selected+1} · 直接编辑</h3>${B('撤回上次调整','idea-undo',false,d.undo?'':'disabled')}</div>${editor('title','故事名称',1)}${editor('hook','故事看点',1)}${editor('conflict','核心冲突',2)}<div class="ss-grid">${editor('characters','人物',3)}${editor('world','世界观',3)}</div>${editor('synopsis','故事梗概',5)}${editor('ending','结局',2)}${plan.requirements?editor('requirements','方案补充要求 · 待融合',2):''}<div class="ss-idea-adopt">${storyLength()}${help(p.story.trim()?'已有稿件 · 重新生成前需确认替换':'尚未生成 · 将整理为结构稿演示')}${B('按此方案生成故事稿','idea-adopt',true)}${storyReplace?storyReplacePrompt():''}${help('携带当前方案编辑内容；本机演示整理结构稿，对话不进入正文。')}</div></div>`:`<div class="ss-idea-empty"><h3>哪个方向让你更想写下去？</h3><p>选一个才展开人物、世界观与梗概；三个方向分别保留手改。</p></div>`}`}</section></div>`;}
function processing(){const w=M.processingWarning(p);return `<div class="ss-grid">${select('processing','怎么处理',[['polish','保留原意润色'],['expand','补充扩写'],['compress','精简压缩'],['adapt','改编分场内容']])}${select('target','目标篇幅建议',[['synopsis','梗概 · 500—1000字'],['scene','一幕 · 800—1500字'],['short','短篇 · 2000—4000字']])}</div>${help('润色默认接近原长；篇幅是产品建议，非模型极限。初版单次建议不超过约4000中文字符。')}<p id="ss-length-warning" class="ss-warning" role="status">${E(w)}</p>`;}
function stage0(){return `<h2>从哪里开始这个故事？</h2><div class="ss-choice">${B('✧ 灵感 / 梗概创作','origin-idea',p.origin==='idea')}${B('▤ 已有内容 · 上传 / 粘贴','origin-import',p.origin==='import')}</div>${input('title','故事名称')}${p.origin==='idea'?field('original','一句灵感 / 故事梗概',4)+`<details><summary>可选设定 · 不必选满</summary><div class="ss-grid">${input('settings.audience','目标受众（可选）')}${input('settings.genre','题材（可选）')}${input('settings.core','核心设定（可选）')}${input('settings.style','风格（标签 + 自定义）')}</div><div class="ss-tags">${['治愈','悬疑','科幻','轻喜剧','青春'].map(t=>B(t,'tag',false,`data-tag="${t}"`)).join('')}</div></details><div class="ss-actions">${B('试用完整样例 · 末班车录音','sample-idea')}</div>`:`<label class="ss-file">上传 TXT / DOCX<input id="ss-upload" type="file" accept=".txt,.docx"></label>${help('仅在本机读取。TXT支持UTF-8/GB18030；DOCX读取正文段落和表格文字。失败可重选。')}${field('original','或粘贴已有小说 / 故事 / 分场内容',5)}<div class="ss-actions">${B('载入小说样例','sample-novel')}${B('载入现成分场内容样例','sample-script')}</div>`}${help(p.importNote||'原文独立保存。未接实时模型；任意输入提供可编辑结构稿，不冒充自动语义理解。')}`;}
function stage1(){if(p.origin==='idea')return `<h2>先选一个想继续写的方向</h2>${help(p.original===ScriptSample.seed?'这是完整内置样例的三种策划，先选一个，再编辑故事。':'以下为围绕你的原文组织的结构方向演示，事实与具体情节由你确认。')}<div class="ss-directions">${p.directions.map((d,i)=>`<article class="ss-card ${p.chosen===i?'selected':''}"><h3>${E(d.title)}</h3><p>${E(d.body)}</p>${B('选择方向 '+(i+1),'direction',true,`data-index="${i}"`)}</article>`).join('')}</div>`;
return `<h2>确认内容，再决定这次处理多少</h2><div class="ss-grid">${select('contentType','纠正内容类型',[['story','完整短故事'],['novel','长篇小说'],['screenplay','现成分场内容']])}<div class="ss-metric">${M.count(p.original)} 字 · ${p.chapters.length} 个章节 / 场次${help('字数按非空白字符统计；可编辑章节标题与边界。')}</div></div><details><summary>解析预览 · 查看全文并校正章节</summary><pre>${E(p.original)}</pre>${p.chapters.map((c,i)=>`<div class="ss-chapter">${input('chapters.'+i+'.title','章节 / 场次 '+(i+1))}<label>起始字符<input type="number" data-bound="${i}" data-edge="start" min="0" max="${p.original.length}" value="${c.start}"></label><label>结束字符<input type="number" data-bound="${i}" data-edge="end" min="0" max="${p.original.length}" value="${c.end}"></label></div>`).join('')}</details>${select('scope','确认本次处理范围',[['full','全文'],['chapter','选择章节 / 场次'],['fragment','选中片段']])}${p.scope==='chapter'?`<div class="ss-chapters">${p.chapters.map(c=>`<label><input type="checkbox" data-chapter="${c.id}" ${p.chapterIds.includes(c.id)?'checked':''}>${E(c.title)} · ${M.count(p.original.slice(c.start,c.end))}字</label>`).join('')}</div>`:p.scope==='fragment'?field('fragment','从原文复制要处理的片段',4)+help('片段必须真实出自原文；确认后保留来源位置，不自动取前N字。'):''}<p id="ss-range-count">当前选中 ${M.count(M.rangeText(p))} 字 · 原文始终保留 ${M.count(p.original)} 字</p>${processing()}${p.contentType==='screenplay'?notice('现成分场内容可直接整理编辑保存，无须重新扩写、策划或生成大纲。')+B('确认范围，直接整理现成分场内容 →','direct',true):''}<details><summary>查看所选范围</summary><pre>${E(M.rangeText(p))}</pre></details>`;}
function storyLength(){return select('target','故事篇幅',[['synopsis','梗概 · 500—1000字'],['scene','一幕 · 800—1500字'],['short','短篇 · 2000—4000字']]);}
function storyReplacePrompt(){return notice('将替换当前稿件，上一版可撤回；下游内容保留。')+B('确认替换当前稿','story-replace',true)+B('取消','story-cancel');}
function ideaStory(){const target={synopsis:'梗概 · 约500—1000字',scene:'一幕 · 约800—1500字',short:'短篇 · 约2000—4000字'}[p.target],name=p.storyDraft?.planTitle||p.ideaDesk?.plans[p.ideaDesk.selected]?.title||p.title;return `<h2>把方案写成故事</h2><p>基于方案《${E(name)}》 · ${target}</p><p class="ss-notice" role="status">${E(M.ideaStoryStatus(p))}</p><details><summary>调整篇幅</summary>${storyLength()}${help('调整篇幅只保存偏好，不会自动覆盖稿件。')}</details>${help(p.storyDraft?.generatedTarget&&p.storyDraft.generatedTarget!==p.target?'篇幅已调整，当前稿件保持原样。':'本机演示不自动生成新情节；结构稿需继续写成正文。')}${field('story','可编辑故事稿',12)}<label>说说你想怎样修改<textarea id="ss-story-request" rows="2" placeholder="例如：让开头更紧凑">${E(p.storyRequest||'')}</textarea></label>${B('完善故事稿','story-refine')}${help('本机仅保存修改要求，待你融合；不会伪装自动改写。')}<div class="ss-actions">${B('按当前方案重新生成','idea-adopt',false,p.ideaDesk?.plans[p.ideaDesk.selected]?'':'disabled')}${B('撤回到上一版','story-undo',false,p.storyDraft?.undo?'':'disabled')}</div>${storyReplace?storyReplacePrompt():''}`;}
function stage2(){if(p.origin==='idea')return ideaStory();return `<h2>把故事改成你想讲的样子</h2>${help(p.processingNote||'完整样例可直接阅读修改；其他输入已保留原文与所选方向，需要你确认具体情节。')}<details><summary>处理方式与目标篇幅 · 按需调整</summary>${processing()}${B('按所选方式整理原范围 · 演示','process')} ${help('此操作会替换下方故事稿，原文和已有下游分场内容保留；已编辑内容请先导出备份。')}</details>${field('story','可编辑故事稿',13)}<details><summary>对照独立原文与设定</summary><pre>${E(p.original)}</pre><p>${E(Object.values(p.settings).filter(Boolean).join(' / '))}</p></details>`;}
function stage3(){return `<h2>先确认事实，再安排剧情</h2>${M.stale(p,'analysis')?notice('故事已有修改，分析待核对。原分析、大纲和手改故事仍保留；可逐项修正后确认。'):''}<div class="ss-analysis">${Object.entries({main:'主线',relations:'人物关系',events:'关键事件',conflict:'核心冲突',timeline:'时间线',foreshadow:'伏笔与回应'}).map(([k,v])=>field('analysis.'+k,v,k==='events'?4:2)).join('')}</div><details open><summary>人物身份与别名 · 故事资产</summary>${p.characters.map((c,i)=>`<article class="ss-person"><div class="ss-grid">${input('characters.'+i+'.name','姓名')}${input('characters.'+i+'.aliases','别名（逗号分隔）')}${input('characters.'+i+'.identity','固定身份')}${input('characters.'+i+'.relation','关系')}${input('characters.'+i+'.state','当前状态')}</div>${help('稳定 ID：'+E(c.id)+'；外貌、服装、参考图留到漫画端补充。')}</article>`).join('')||help('尚未识别人物。请按原文添加，不会把样例角色套到你的故事里。')}<div class="ss-add"><label>新增人物姓名 / 已有别名<input id="ss-new-person"></label><label>别名（可选）<input id="ss-new-alias"></label>${B('添加 / 定位人物','add-person')}</div></details><details><summary>世界、地点与关键道具</summary>${field('facts','世界与不可改事实',3)}${p.places.map((x,i)=>`<div class="ss-grid">${input('places.'+i+'.name','地点名称')}${input('places.'+i+'.role','剧情作用')}</div>`).join('')}${B('添加地点','add-place')}${p.props.map((x,i)=>`<div class="ss-grid">${input('props.'+i+'.name','关键道具')}${input('props.'+i+'.role','剧情作用')}</div>`).join('')}${B('添加道具','add-prop')}</details>${B('已逐项核对事实 · 确认分析','confirm-analysis')}<span id="ss-fact-status">${p.analysisConfirmed?' 已确认':' 待你确认'}</span>`;}
function stage4(){return `<h2>一集一件事，让变化有落点</h2>${M.stale(p,'outline')?notice('上游事实或故事有修改。大纲待核对，已写故事不会被覆盖。'):''}${!p.outline.length?`<label>计划集数<input id="ss-episode-count" type="number" min="1" max="12" value="2"></label>${B('按原文顺序整理分集大纲','outline',true)}${help('本机按段落分配原内容；不是长小说语义分析。每集事件、变化与结尾都可改。')}`:`<p>${p.outline.length} 集 · 拆分增加一集，合并接下一集，顺序可上下移动。</p>${p.outline.map((e,i)=>`<article class="ss-card"><div class="ss-episode-head"><strong>第 ${i+1} 集</strong><div>${B('↑','move-up',false,`data-id="${e.id}" aria-label="上移第${i+1}集" ${i===0?'disabled':''}`)}${B('↓','move-down',false,`data-id="${e.id}" aria-label="下移第${i+1}集" ${i===p.outline.length-1?'disabled':''}`)}${B('拆分','split',false,`data-id="${e.id}"`)}${B('与下一集合并','merge',false,`data-id="${e.id}" ${i===p.outline.length-1?'disabled':''}`)}</div></div>${e.phaseNote?help(E(e.phaseNote)):''}${input('outline.'+i+'.title','集名')}${field('outline.'+i+'.events','本集事件',4)}<div class="ss-grid">${field('outline.'+i+'.change','人物变化',2)}${field('outline.'+i+'.ending','结尾 / 悬念',2)}</div>${help(p.scripts[e.id]?'已有手改故事，调整规划仅标记待核对。':'尚未整理本集内容。')}</article>`).join('')}${help('合并时被并集的故事会留在归档，可查看和导出；不会覆盖保留集的手改。')}${B('已核对大纲与上游关系','confirm-outline')}`}`;}
function stage5(){const e=p.outline.find(x=>x.id===p.selectedEpisode)||p.outline[0];if(!e)return '<h2>先去分集大纲安排一集内容</h2>';p.selectedEpisode=e.id;const script=p.scripts[e.id],i=Math.min(p.selectedScene||0,(script?.scenes.length||1)-1);p.selectedScene=i;const s=script?.scenes[i];return `<h2>一集一场，慢慢把话写出来</h2><div class="ss-script-toolbar"><label>当前集<select id="ss-episode">${p.outline.map(x=>`<option value="${x.id}" ${e.id===x.id?'selected':''}>${E(x.title)}${p.scripts[x.id]?' · 已整理':''}</option>`).join('')}</select></label>${script?B('＋ 添加场次','add-scene'):B('整理这一集分场内容 · 本机演示','write',true)}</div>${details()}${script?`${M.stale(p,'scripts',e.id)?notice('本集的上游规划已修改，分场内容待核对。以下手改内容保持原样；核对后可确认沿用。')+B('已核对，沿用本集手改','keep-script'):''}<div class="ss-scene-tabs">${script.scenes.map((x,j)=>B('场'+(j+1),'scene',j===i,`data-index="${j}"`)).join('')}</div><div class="ss-grid">${input('scripts.'+e.id+'.scenes.'+i+'.time','时间 / 内外景')}${input('scripts.'+e.id+'.scenes.'+i+'.place','地点')}</div><div class="ss-character-picks"><span>出场人物</span>${p.characters.map(c=>`<label><input type="checkbox" data-scene-person="${c.id}" ${s.characterIds.includes(c.id)?'checked':''}>${E(c.name)}${c.aliases?' / '+E(c.aliases):''}</label>`).join('')||help('到剧情分析添加人物身份。')}</div>${field('scripts.'+e.id+'.scenes.'+i+'.action','动作 / 场景',5)}<div class="ss-grid">${field('scripts.'+e.id+'.scenes.'+i+'.dialogue','对白（姓名：台词）',5)}${field('scripts.'+e.id+'.scenes.'+i+'.mind','心理 / 旁白',5)}</div>${B('局部重写 · 手动演示','rewrite')}${rewriteOpen?`<div class="ss-card"><p>未接模型：只将你输入的新动作应用到当前场，其他场不动。</p><label>当前场替换动作<textarea id="ss-rewrite" rows="4">${E(s.action)}</textarea></label>${B('应用到当前场动作','apply-rewrite',true)}${B('取消','cancel-rewrite')}</div>`:''}<details><summary>本集结束状态与伏笔</summary>${field('outline.'+p.outline.indexOf(e)+'.state','本集结束时的人物 / 道具状态',2)}${field('outline.'+p.outline.indexOf(e)+'.foreshadow','延续到下一集的伏笔',2)}</details>${help(script.demo?'已按原文段落整理动作结构；未自动补写对白，请按场编辑。':'由现成分场内容整理，保留原场次和对白。')}`:notice('本集还没有故事。点击“整理这一集”后逐场编辑，不会一次性宣称完成整部长篇。')}<details><summary>已归档的合并前故事</summary><pre>${E(JSON.stringify(p.archivedScripts||{},null,2))}</pre></details>`;}
function stage6(){const a=state.assets.find(a=>a.assetId===p.savedAssetId),dirty=M.assetStale(p,a);return `<h2>保存故事，继续视觉创作</h2><div class="ss-card"><h3>${E(p.title)}</h3><p>${p.outline.length} 集规划 · ${Object.keys(p.scripts).length} 集已有故事 · ${p.characters.length} 位固定身份人物</p>${notice(a?(dirty?'工程已修改，已保存资产仍是旧快照。请明确更新资产；已有漫画和视频不会被同步覆盖。':'已保存故事资产，资产库可见。新漫画将复制此份来源快照。'):'尚未保存故事资产。保存包含原文、设定、分析、大纲、故事与来源。')}${B(a?'更新故事资产 · 明确发布当前稿':'保存为故事工程资产','publish',true)}${B('导出当前故事 TXT','export-text')}<p><a href="#/app/assets?type=scripts" class="cm-text-link">查看故事资产列表 →</a></p></div>${a?`<div class="ss-card"><h3>选择整部或某集，开始视觉创作</h3><label>使用范围<select id="ss-handoff-episode"><option value="">整部（每集都需有故事）</option>${a.outline.map(e=>`<option value="${e.id}">${E(e.title)}${a.scripts[e.id]?'':' · 尚未有故事'}</option>`).join('')}</select></label><p>将复制资产 ${E(a.title)} 的已保存快照，人物ID与来源保留；漫画端再补外貌、服装和参考图。</p>${B('从所选故事新建漫画 →','comic',true)}${B('从所选故事新建视频方案 →','video')}${help('不会覆盖任何已有漫画、视频或草稿。后续故事修改不会静默同步。')}</div>`:''}${details()}`;}
// 同一时刻只展示起点或工作区；stage继续兼容既有工程。
let useOpen=p.stage===6,personId='',restartConfirm=false,personCreate=false;
const workTab=()=>p.stage===3?'people':p.stage===4?'outline':p.stage>=5?'body':'overview';
function planReading(plan){const v=(key,fallback='待补充')=>E(plan[key]?.trim()||fallback);return `<article class="ss-plan-reading"><header><small>${plan.kind==='authored-example'?'人工完整创作策划示范 · 未调用模型':plan.kind==='sample'?'完整预制策划样例':plan.kind==='structure'?'任意输入 · 结构演示':'已保存方案'}</small><h3>${v('title','未命名故事')}</h3></header><dl class="ss-plan-meta"><div><dt>目标读者</dt><dd>${v('audience','未限定')}</dd></div><div><dt>故事类型</dt><dd>${v('genre')}</dd></div><div><dt>核心设定</dt><dd>${v('core')}</dd></div></dl>${[['style','情绪 / 风格'],['hook','核心亮点'],['world','世界观'],['synopsis','核心梗概']].map(([key,label])=>`<section><h4>${label}</h4><p>${v(key)}</p></section>`).join('')}${plan.kind==='structure'?`<p class="ss-help">${plan.recommendation?E(plan.recommendation):'未接模型；原方案字段保留，尚未补充的内容由你确认。'}</p>`:''}</article>`;}

function importPreview(){const a=p.importAnalysis,valid=a?.sourceText===p.original;if(!a)return `<div class="ss-start-empty"><span>▤</span><h3>先认识这份素材</h3><p>上传或粘贴故事，点击分析内容；也可以试用完整示范。</p></div>`;return `<div class="ss-import-overview"><p id="ss-import-valid" class="ss-help">${valid?(a.kind==='demo'?'示范案例 · 全文预置分析':'本机仅核对文字与首尾摘录，语义待分析；未接模型。'):'原文已变化，请重新分析。'}</p><section><h3>素材信息</h3><p>${E(p.sourceName||'粘贴原文')} · 全文 ${M.count(p.original)} 字${a.chapterCount?' · '+a.chapterCount+' 个明确章节':''}</p><p class="ss-help">${E(a.extractionScope)}${a.kind==='extraction'?' · 语义分析0字':''}</p></section><section><h3>题材与类型</h3><div class="ss-import-tags">${a.genre?a.genre.split(/[·、,，]/).filter(x=>x.trim()).map(x=>`<span>${E(x.trim())}</span>`).join(''):'<span>暂无法判断</span>'}</div><details class="ss-import-adjust"><summary>修正题材</summary><input data-import-field="genre" aria-label="题材与类型" value="${E(a.genre)}" placeholder="暂无法判断，可自行补充"></details><p>${E(a.genreReason||'未做语义判断，不预设题材。')}</p></section><section><h3>受众推荐</h3><strong class="ss-import-audience">${E(a.audience||'暂无法判断')}</strong><details class="ss-import-adjust"><summary>修正受众</summary><input data-import-field="audience" aria-label="受众推荐" value="${E(a.audience)}" placeholder="暂无法判断，可自行补充"></details><p>${E(a.audienceReason||'信息不足，推荐待补充。')}</p></section><section><h3>主角故事概要</h3><p>${E(a.main||'主角、目标、阻碍与经历暂无法可靠提取，进入后可据原文补充。')}</p></section><section><h3>主要配角</h3>${a.supporting.length?a.supporting.map(c=>`<p><strong>${E(c.name)}</strong> · ${E(c.relation)}。${E(c.background)}</p>`).join(''):'<p>尚未可靠识别，保留空白。</p>'}</section>${B('进入故事工作区','start-import',true,valid?'':'disabled')}</div>`;}
function importSourceView(){return p.sourceAuthority?`<details class="ss-import-source"><summary>原文依据 · ${M.count(p.original)}字${p.sourceNeedsReview?' · 已变更，待核对':''}</summary><p class="ss-help">${p.importAnalysis?.kind==='demo'?'示范概要':'当前为原文摘录，语义待核对'}；分集与正文独立关联原文，不以概要替代。</p>${p.importRequest?`<p>改编要求（独立保留）：${E(p.importRequest)}</p>`:''}<pre>${E(p.original)}</pre></details>`:'';}

function startView(){const d=p.ideaDesk,previewIndex=d?.plans[d.selected]?d.selected:0,plan=d?.plans[previewIndex];return `<div class="ss-start-grid"><section class="ss-start-input ss-idea-chat"><div class="ss-start-input-heading"><h2>${p.origin==='idea'?'从一个想法开始':'让已有故事继续生长'}</h2>${p.origin==='import'?B('试用示范案例','import-sample',false,'title="完整短故事；已有输入时另建示范项目"'):''}</div><div class="ss-choice">${B('写灵感','origin-idea',p.origin==='idea')}${B('上传或粘贴','origin-import',p.origin==='import')}</div>${p.origin==='idea'?`${field('original','一句灵感 / 故事梗概',5)}${preferences()}<div class="ss-start-cta">${d?.plans.length?B('重新构思','idea-restart'):B('帮我构思','idea-start',true)}</div>${!d?.plans.length?B('体验完整策划样例','plan-sample'):''}${B('体验全流程示例','full-example',false,'title="人工创作的10集爱情故事；点击另建项目，不替换当前输入"')}`:`<label class="ss-file">上传 TXT / DOCX<input id="ss-upload" type="file" accept=".txt,.docx"></label>${field('original','粘贴已有故事',6)}${field('importRequest','补充创作要求（可选）',2)}${B('分析内容','start-parse',true)}`}${restartConfirm?notice('重新构思会替换当前三个方向，旧方向完整归档；已写故事不变。')+B('确认重新构思','idea-restart-confirm',true)+B('取消','idea-restart-cancel'):''}${help('本机结构演示 · 未接模型')}</section><section class="ss-start-preview"><h2>${p.origin==='idea'?'选择你想讲的故事':'素材分析概览'}</h2>${p.origin==='idea'?(d?.plans.length?`<div class="ss-direction-switches">${d.plans.map((x,i)=>`<article class="ss-direction-row ${i===previewIndex?'selected':''}"><h3>${E(x.title)}</h3><p>${E(x.hook)}</p>${B(i===previewIndex?'已选中':'选择这个方向','idea-choose',i===previewIndex,`data-index="${i}"`)}</article>`).join('')}</div>${plan?`<p class="ss-help">当前预览 · 尚未采用</p>${planReading(plan)}<div class="ss-start-cta ss-plan-adopt">${B('用这个方向继续 →','idea-adopt',true)}</div>`:help('选一个方向后继续，进入工作区仍可编辑。')}`:p.directions.length?stage1():`<div class="ss-start-empty"><span>✧</span><h3>一个想法，就可以开始</h3><p>写下灵感，这里会出现三个可选方向。</p></div>`):importPreview()}</section></div>`;}
function fullExampleReview(){if(!p.exampleCase)return '';return `<details class="ss-full-example-review"><summary>回看创作路径 · 灵感 → 策划 → 10集正文</summary><p class="ss-help">人工完整创作示例《${E(p.exampleCase.storyTitle)}》 · 未调用模型。载入时逐步经过现有工程模型，以下为只读过程记录；不会倒退或改写当前稿件。</p><h4>用户原始灵感</h4><p>${E(p.original)}</p><h4>独立创作要求</h4><p>${E(p.creationRequirements)}</p><p>${p.exampleHistory.map(x=>({seed:'写灵感',directions:'3个方向策划',adopt:'采用方案快照',overview:'故事概览',characters:'固定人物身份',outline:'10集分集规划',body:'全部正文完成'})[x.step]).join(' → ')}</p>${p.ideaDesk.plans.map((plan,i)=>`<details><summary>方向${i+1} · ${E(plan.title)}${i===p.chosen?' · 已采用':' · 仅备选策划'}</summary>${planReading(plan)}<h4>核心冲突</h4><p>${E(plan.conflict)}</p><h4>结局安排</h4><p>${E(plan.ending)}</p></details>`).join('')}<p class="ss-help">正文10集均为完整稿，前后关系与倒计时已核对；角色未包含视觉资产；故事资产仅由你显式保存，不会自动发布。</p></details>`;}
function overviewView(){return `<h2>故事概览</h2>${input('title','故事名称')}${fullExampleReview()}<div class="ss-overview-meta">${['genre','audience','style'].map(k=>p.settings[k]?'<span>'+E(p.settings[k])+'</span>':'').join('')}<small>${p.exampleCase?'人工完整创作示例 · 10集正文已写好':p.origin==='idea'?E(M.ideaStoryStatus(p)):(p.sourceAuthority?'原文独立保留 · 概要可编辑':'已带入选中原文 · 可直接编辑')}</small></div>${p.adoptedPlan?`<details class="ss-adopted-plan"><summary>已采用的完整策划 · 只读对照</summary>${planReading(p.adoptedPlan)}</details>`:''}${importSourceView()}${field('story','故事梗概 / 当前故事稿',11)}${B('撤回梗概上一版','story-undo',false,p.storyDraft?.undo?'':'disabled')}<div class="ss-main-next">${B('继续完善人物 →','work-people',true)}</div>`;}
let characterDraft=null,traitDraft='';
function activeCharacter(){return characterDraft||p.characters.find(c=>c.id===(personId||p.selectedPersonId))||p.characters[0];}
function peopleView(){const c=activeCharacter(),tags=c?.personalityTags||[];const control=(key,label,area=false)=>`<label>${label}${area?`<textarea rows="4" data-character="${key}">${E(c?.[key]||'')}</textarea>`:`<input data-character="${key}" value="${E(c?.[key]||'')}" ${key==='age'?'placeholder="未设定"':key==='gender'?'placeholder="未设定 / 可自定义"':''}>`}</label>`;return `<div class="ss-people-heading"><div><h2>${characterDraft?'创建角色':'人物'}</h2><p class="ss-help">${characterDraft?'填写角色资料后创建':'本机整理 · 资料可直接编辑'}</p></div><div>${!characterDraft?B('AI补全全部角色','people-complete',true):''}${!characterDraft&&p.characterUndo?B('撤回本次补全','people-undo'):''}</div></div><div class="ss-character-desk"><section class="ss-character-editor">${c?`<div class="ss-grid">${control('name','姓名')}<label>定位<select data-character="role">${[['','未设定'],['主角','主角'],['重要配角','重要配角'],['配角','配角'],...(c.role&&!['主角','重要配角','配角'].includes(c.role)?[[c.role,c.role]]:[])].map(([v,t])=>`<option value="${v}" ${c.role===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="ss-grid">${control('age','年龄')}${control('gender','性别')}</div><label>性格<div class="ss-trait-tags">${tags.map((t,i)=>B(E(t)+' ×','trait-remove',false,`data-index="${i}" aria-label="删除性格标签 ${E(t)}"`)).join('')}</div><input id="ss-trait-input" value="${E(traitDraft)}" placeholder="输入性格，Enter 或空格添加"></label>${control('background','角色背景',true)}`:''}</section><section class="ss-character-roster" aria-label="角色选择"><div class="ss-character-cards">${p.characters.map(x=>`<button class="ss-character-card ${!characterDraft&&x.id===c?.id?'selected':''}" data-ss="person-select" data-id="${x.id}"><strong>${E(x.name||'未命名角色')}</strong><span>${E(x.role||'定位待确认')}</span></button>`).join('')}<button class="ss-character-card ss-character-add" data-ss="people-add-open"><strong>＋</strong><span>创建角色</span></button></div></section></div><div class="ss-main-next">${characterDraft?B('取消','people-create-cancel')+B('创建角色','people-create-submit',true):B('继续分集大纲 →','work-outline',true)}</div>`;}
let outlineProposal=null,outlineConfirm=null,episodeRequest='';
function outlineView(){const settings=M.outlineSettings(p),recommendation=M.outlineRecommendation(p),groups=M.stageGroups(p),group=groups.find(g=>g.id===p.selectedPhase)||groups[0],all=p.outlineShowAll!==false,visible=all?p.outline:(group?.episodes||[]),stale=p.outline.length&&(!p.outlineBasis||p.outlineBasis.story!==p.revisions.story||p.outlineBasis.analysis!==p.revisions.analysis);return `<h2>分集大纲</h2><div class="ss-length-bar"><label>篇幅<select id="ss-plan-mode">${[['compact','精简版 · 减少支线'],['standard','标准版 · 完整主线'],['expanded','展开版 · 发展空间']].map(([k,t])=>`<option value="${k}" ${settings.mode===k?'selected':''}>${t}</option>`).join('')}</select></label><label>集数<input id="ss-plan-count" type="number" min="1" max="12" value="${settings.count}"></label>${B(p.outline.length?'重新规划':'生成分集大纲','plan-outline',true)}</div>${stale?notice('上游故事或人物已变化：现有集纲保留，以下各阶段待核对。确认重新规划后才替换。'):''}${outlineProposal?`<div class="ss-outline-confirm"><strong>确认替换为 ${outlineProposal.episodes.length} 集？</strong><p>${E(outlineProposal.note)}旧集纲将归档，已有正文保留，需按新规划人工核对。</p>${B('确认替换规划','plan-apply',true)}${B('取消','plan-cancel')}</div>`:''}${outlineConfirm?`<div class="ss-outline-confirm"><p>${outlineConfirm.kind==='phase'?'只重排当前阶段已有事件段落；手改将被替换，上一版可撤回。':outlineConfirm.kind==='split'?'拆为两集，原正文保留在原集，新集正文待整理。':'合并相邻两集，保留首集正文，下一集正文完整归档。'}不会自动重写正文。</p>${B('确认本次调整','plan-mutation-confirm',true)}${B('取消','plan-cancel')}</div>`:''}${group?`<div class="ss-outline-columns"><section class="ss-outline-list" aria-label="分集集纲"><div class="ss-outline-filter"><h3>${all?'全部集纲':E(group.label)+' · 第'+group.start+'—'+group.end+'集'}</h3>${B('全部集纲','plan-show-all',all)}</div>${visible.map(e=>{const i=p.outline.indexOf(e);return `<article class="ss-card ss-outline-episode"><div class="ss-episode-head"><strong>第 ${i+1} 集${stale?' · 待核对':''}</strong><div>${B('AI修改','plan-episode-request',false,`data-id="${e.id}"`)}${B('拆为两集','plan-split',false,`data-id="${e.id}"`)}</div></div>${field('outline.'+i+'.events','本集内容',5)}${e.modificationRequest?help('待融合要求：'+E(e.modificationRequest)):''}${episodeRequest===e.id?`<label>本集修改要求<textarea id="ss-outline-request" rows="2">${E(e.requestDraft||'')}</textarea></label>${B('记录本集修改要求','plan-episode-save',true,`data-id="${e.id}"`)}${help('本机仅记录待融合要求，不自动改写集纲。')}`:''}${p.scripts[e.id]?help('已有正文 · 本次规划修改不会自动重写'):''}</article>`;}).join('')}</section><aside class="ss-outline-structure" aria-label="总纲与阶段粗纲"><h3>故事结构</h3><details><summary>总纲</summary><pre>${E(p.overallOutline||p.story)}</pre></details>${groups.map(g=>`<details class="ss-structure-phase ${!all&&g.id===group?.id?'selected':''}" ${g.id===group?.id?'open':''}><summary data-phase-select="${g.id}">${E(g.label)} · ${g.start===g.end?'第'+g.start+'集':g.start+'—'+g.end+'集'}</summary><p class="ss-help">${E(g.title)}</p><label>阶段粗纲<textarea data-phase-direction="${g.id}" rows="5">${E(g.direction)}</textarea></label>${B('仅更新当前阶段','plan-update-phase',false,`data-id="${g.id}"`)}</details>`).join('')}</aside></div>`:help('先确认篇幅与集数，再生成可编辑集纲。')}<div class="ss-main-next">${B('继续正文 →','work-body',true)}</div>`;}
function handleOutline(action,ep){if(action==='plan-show-all'){p.outlineShowAll=true;}else if(action==='plan-outline'){const proposal=M.planOutline(p);if(p.outline.length)outlineProposal=proposal;else M.applyOutlinePlan(p,proposal);}else if(action==='plan-apply'){M.applyOutlinePlan(p,outlineProposal);outlineProposal=null;message='规划已更新；旧集纲与正文保持可恢复。';}else if(action==='plan-cancel'){outlineProposal=null;outlineConfirm=null;}else if(action==='plan-undo'){M.undoOutline(p);message='已恢复上一版规划，正文保留。';}else if(action==='plan-phase'){p.selectedPhase=ep;p.outlineShowAll=false;}else if(action==='plan-split'||action==='plan-merge'){outlineConfirm={kind:action==='plan-split'?'split':'merge',id:ep};}else if(action==='plan-update-phase'){outlineConfirm={kind:'phase',id:ep||p.selectedPhase||M.stageGroups(p)[0]?.id};}else if(action==='plan-mutation-confirm'){if(outlineConfirm.kind==='phase'){const group=M.stageGroups(p).find(g=>g.id===outlineConfirm.id),before=M.outlineSnapshot(p),parts=group.direction.split(/\n\s*\n|(?<=[。！？])\s*/).filter(Boolean);group.episodes.forEach((e,i)=>{e.events=parts.slice(Math.floor(i*parts.length/group.episodes.length),Math.floor((i+1)*parts.length/group.episodes.length)).join('\n')||'待补充阶段中的本集事件';});M.touch(p,'outline');p.outlineUndo={before,after:M.outlineSnapshot(p)};}else M.outlineMutation(p,outlineConfirm.kind,outlineConfirm.id);outlineConfirm=null;}else if(action==='plan-episode-request'){episodeRequest=ep;}else if(action==='plan-episode-save'){const e=p.outline.find(e=>e.id===ep);e.modificationRequest=e.requestDraft||'';M.touch(p,'outline');episodeRequest='';message='本集修改要求已保存，待融合。';}}
let bodySettingsOpen=false,bodyConfirm=null,bodyFocus=null,bodyRequest='',focusText='',bodyBatchConfirm=null;
function bodyView(){const settings={preset:'standard',target:1200,language:'zh',...(p.bodySettings||{})},opened=M.bodyOpened(p),selected=p.outline.find(e=>e.id===p.bodySelectedId)||p.outline[0],next=p.outline.find(e=>!opened.includes(e.id));return `<div class="ss-body-heading"><h2>正文</h2><div class="ss-body-tools">${B('每集篇幅 · '+settings.target+(settings.language==='zh'?'字':'词'),'body-settings')}<details class="ss-body-batch"><summary>批量生成</summary><div>${[3,5,10].map(n=>B('生成'+n+'集','body-batch',false,'data-id="'+n+'"')).join('')}</div></details></div></div>${!selected?notice('尚无分集大纲，请先安排集数。')+B('前往分集大纲','work-outline',true):`<div class="ss-body-desk"><div class="ss-body-cards">${p.outline.map((e,i)=>{if(!opened.includes(e.id))return '';const text=M.bodyText(p,e.id),count=M.bodyCount(text,settings.language);return `<article class="ss-body-card ${selected.id===e.id?'selected':''} ${text.trim()?'':'is-empty'}" id="body-${e.id}"><header><h3>第 ${i+1} 集</h3><span data-body-count="${e.id}">${count.value} ${count.unit}</span>${B('展开编辑','body-focus',false,`data-id="${e.id}"`)}</header><textarea data-body-text="${e.id}" aria-label="第${i+1}集正文" placeholder="粘贴或写下本集正文，也可以生成结构演示。">${E(text)}</textarea><div class="ss-actions">${B(text?'AI修改':'AI生成','body-generate',true,`data-id="${e.id}"`)}${text?B('清空正文','body-clear',false,`data-id="${e.id}"`):''}${p.bodyUndo?.id===e.id?B('撤回上次替换','body-undo',false,`data-id="${e.id}"`):''}</div>${bodyRequest===e.id?`<label>本集修改要求<textarea id="ss-body-request" rows="2">${E(p.scripts[e.id]?.requestDraft||'')}</textarea></label>${B('记录修改要求','body-request-save',false,`data-id="${e.id}"`)}${B('重新生成演示','body-regenerate',false,`data-id="${e.id}"`)}`:''}${p.scripts[e.id]?.bodyRequests?.length?help('待融合要求：'+E(p.scripts[e.id].bodyRequests.at(-1))):''}${p.scripts[e.id]?.bodyDemo?help('结构演示 · 未接模型，需继续写成正文。'):''}</article>`;}).join('')}${next?B('＋ 添加下一集正文','body-open',false,`data-id="${next.id}" class="ss-body-add"`):help('全部大纲集已打开')}</div><aside class="ss-body-reference" aria-label="集纲对照"><nav class="ss-body-index" aria-label="集数选择">${p.outline.map((e,i)=>B('第'+(i+1)+'集','body-jump',selected.id===e.id,`data-id="${e.id}" aria-current="${selected.id===e.id?'true':'false'}"`)).join('')}</nav><section><h3>第 ${p.outline.indexOf(selected)+1} 集 · 集纲</h3><p class="ss-body-outline">${E(selected.events)}</p>${!opened.includes(selected.id)?B('开始本集正文','body-open',true,`data-id="${selected.id}"`):''}</section></aside></div>`}${bodyBatchConfirm?`<div class="ss-use-backdrop"><section class="ss-body-modal cm-panel" role="dialog" aria-label="批量生成确认"><h2>批量生成结构演示</h2><p>请求${bodyBatchConfirm.requested}集，实际可生成${bodyBatchConfirm.ids.length}集：${bodyBatchConfirm.ids.map(id=>'第'+(p.outline.findIndex(e=>e.id===id)+1)+'集').join('、')||'无'}。</p><p>从当前选中集向后，跳过已有正文；仅整理结构演示，未接模型。</p>${bodyBatchConfirm.ids.length?B('确认生成','body-batch-confirm',true):''}${B('取消','body-batch-cancel')}</section></div>`:''}${bodySettingsOpen?`<div class="ss-use-backdrop"><section class="ss-body-modal cm-panel" role="dialog" aria-label="每集篇幅"><h2>每集篇幅</h2><label>计数语言<select id="ss-body-language"><option value="zh" ${settings.language==='zh'?'selected':''}>中文 · 计字</option><option value="latin" ${settings.language==='latin'?'selected':''}>拉丁语言 · 计词</option></select></label><label>目标篇幅<select id="ss-body-preset">${[['short','简短 · 约800'],['standard','标准 · 约1200'],['detailed','详细 · 约1800'],['custom','自定义']].map(([k,t])=>`<option value="${k}" ${settings.preset===k?'selected':''}>${t}</option>`).join('')}</select></label>${settings.preset==='custom'?`<label>目标数量<input id="ss-body-target" type="number" min="1" value="${settings.target}"></label>`:''}<p class="ss-help">目标范围，非精确硬数；仅影响之后生成，不重写现有稿。本机演示不保证达到目标。</p>${B('完成','body-settings-close',true)}</section></div>`:''}${bodyConfirm?`<div class="ss-use-backdrop"><section class="ss-body-modal cm-panel" role="dialog" aria-label="确认正文操作"><h2>${bodyConfirm.kind==='clear'?'清空本集正文？':'替换本集正文？'}</h2><p>上一版保留可撤回，仅影响本集文字，不删除集纲、其他集和已保存资产。</p>${B('确认','body-confirm',true)}${B('取消','body-cancel')}</section></div>`:''}${bodyFocus?`<div class="ss-use-backdrop"><section class="ss-focus-body cm-panel" role="dialog" aria-label="专注编辑"><header><h2>第 ${p.outline.findIndex(e=>e.id===bodyFocus)+1} 集 · 专注编辑</h2><div>${B('保存并退出','body-focus-save',true)}${B('取消本次编辑','body-focus-cancel')}</div></header><textarea id="ss-focus-text" aria-label="专注正文">${E(focusText)}</textarea><p class="ss-help">当前为编辑草稿，保存后写入本集；取消不覆盖原文。</p></section></div>`:''}`;}
function generateBody(id){const e=p.outline.find(e=>e.id===id);if(!e)throw Error('找不到本集集纲。');const source=M.bodySource(p,id);p.bodyUndo={id,text:M.bodyText(p,id)};M.setBody(p,id,`场景1 地点待确认 · 日夜/内外待确认\n出场人物：${p.characters.map(c=>c.name).join('、')||'待确认'}\n\n${e.events}\n\n【结构演示】依据本集集纲整理动作，角色对白待补充。`);p.bodyUndo.after=M.bodyText(p,id);p.scripts[id].bodyDemo=true;p.scripts[id].sourceBasis={...source,outline:e.events,characterIds:p.characters.map(c=>c.id),requirements:p.importRequest||''};p.scripts[id].generationSources={overview:p.revisions.story,outline:p.revisions.outline,characters:p.characters.map(c=>c.id),target:p.bodySettings?.target||1200};}
function handleBody(action,id){if(action==='body-batch'){bodyBatchConfirm={requested:+id,ids:M.bodyBatch(p,p.bodySelectedId||p.outline[0]?.id,+id)};}else if(action==='body-batch-cancel')bodyBatchConfirm=null;else if(action==='body-batch-confirm'){let count=0;for(const id of bodyBatchConfirm.ids){if(M.bodyText(p,id).trim())continue;generateBody(id);M.openBody(p,id);count++;}message='已生成'+count+'集结构演示，未接模型；已有稿保留。';bodyBatchConfirm=null;}else if(action==='body-open'){M.openBody(p,id);p.bodySelectedId=id;}else if(action==='body-settings')bodySettingsOpen=true;else if(action==='body-settings-close')bodySettingsOpen=false;else if(action==='body-jump'){p.bodySelectedId=id;render();$('#body-'+id)?.scrollIntoView({block:'start',behavior:'smooth'});return;}else if(action==='body-focus'){bodyFocus=id;focusText=M.bodyText(p,id);}else if(action==='body-focus-save'){M.setBody(p,bodyFocus,focusText);bodyFocus=null;}else if(action==='body-focus-cancel')bodyFocus=null;else if(action==='body-generate'){if(M.bodyText(p,id).trim())bodyRequest=bodyRequest===id?'':id;else generateBody(id);}else if(action==='body-regenerate')bodyConfirm={kind:'generate',id};else if(action==='body-clear')bodyConfirm={kind:'clear',id};else if(action==='body-cancel')bodyConfirm=null;else if(action==='body-confirm'){const c=bodyConfirm;if(c.kind==='clear'){p.bodyUndo={id:c.id,text:M.bodyText(p,c.id)};M.setBody(p,c.id,'');p.bodyUndo.after='';}else generateBody(c.id);bodyConfirm=null;}else if(action==='body-undo'){if(p.bodyUndo.after!==undefined&&M.bodyText(p,id)!==p.bodyUndo.after)throw Error('替换后已有手改，未覆盖当前正文；上一版仍保留。');M.setBody(p,id,p.bodyUndo.text);delete p.bodyUndo;}else if(action==='body-request-save'){const s=p.scripts[id];if(!s.requestDraft?.trim())throw Error('先填写修改要求。');s.bodyRequests??=[];s.bodyRequests.push(s.requestDraft);s.requestDraft='';bodyRequest='';message='修改要求已记录，待融合；正文保留。';}}

function assistantView(){const tab=workTab(),a=p.workAssistant?.[tab]||{messages:[]};return `<aside class="ss-assistant cm-panel"><h2>${tab==='overview'?'完善故事梗概':'一起完善故事'}</h2><p class="ss-help">${({overview:'仅完善故事梗概',people:'人物与关系',outline:'分集与节奏',body:'当前集与场次'})[tab]} · 修改要求待你融合</p><div class="ss-assistant-log">${!a.messages.length?'<p>哪里还想调整？说说你的想法。</p>':a.messages.map(x=>`<article><strong>你</strong><p>${E(x)}</p><small>已记录 · 待融合</small></article>`).join('')}</div><label>${tab==='overview'?'说说梗概想怎么改':'说说你想怎么改'}<textarea id="ss-work-request" rows="3" placeholder="${tab==='overview'?'例如：让开头更紧凑':'例如：让主角更主动一些'}">${E(a.draft||'')}</textarea></label><div class="ss-actions">${B('记录修改要求','work-refine',true)}${B('撤回','work-undo',false,a.messages.length?'':'disabled')}</div></aside>`;}
function render(){if(!alive)return;const start=p.stage<2,tab=workTab();if(!start&&tab==='people'&&!p.characters.length)M.ensureCharacters(p);host.innerHTML=`<div class="ss-project-tools"><a href="#/app" class="cm-text-link">← 创作空间</a><label class="ss-project-select">故事项目<select id="ss-projects">${(!state.projects.some(x=>x.id===p.id)?[p,...state.projects]:state.projects).map(x=>`<option value="${x.id}" ${p.id===x.id?'selected':''}>${E(x.title)}</option>`).join('')}</select></label></div><div class="ss-heading"><div><span class="cm-kicker">STORY STUDIO</span><h1>${start?'开始你的故事':E(p.title)}</h1></div><div class="ss-heading-actions"><span id="ss-save" role="status">${state.projects.some(x=>x.id===p.id)?'已自动保存':'开始填写后自动保存'}</span>${!start?B('使用故事','use-open',true):''}</div></div>${!start?`<nav class="ss-work-tabs" aria-label="故事工作区">${[['overview','故事概览'],['people','人物'],['outline','分集大纲'],['body','正文']].map(([k,t])=>B(t,'work-'+k,tab===k,`aria-current="${tab===k?'page':'false'}"`)).join('')}</nav>`:''}<p id="ss-message" role="status">${E(message)}</p>${start?`<section class="ss-body cm-panel ss-start-body" aria-label="统一创作起点">${startView()}</section>`:`<div class="ss-work-layout ${tab==='people'?'ss-people-only':tab==='outline'?'ss-outline-wide':tab==='body'?'ss-body-wide':''}"><section class="ss-body cm-panel ss-work-main" aria-label="${({overview:'故事概览',people:'人物',outline:'分集大纲',body:'正文'})[tab]}">${({overview:overviewView,people:peopleView,outline:outlineView,body:bodyView})[tab]()}</section>${['people','outline','body'].includes(tab)?'':assistantView()}</div>`}${useOpen&&!start?`<div class="ss-use-backdrop"><section class="ss-use-panel cm-panel" role="dialog" aria-modal="true" aria-label="使用故事"><div class="ss-use-head"><h2>使用故事</h2>${B('关闭','use-close')}</div>${stage6()}</section></div>`:''}`;bind();if(state.projects.some(x=>x.id===p.id))save();window.scrollTo({top:0,behavior:'instant'});}

function validateRange(){let t=M.rangeText(p);if(!t.trim())throw Error('请选择非空章节或片段。');if(p.scope==='fragment'){let n=p.original.indexOf(p.fragment);if(n<0)throw Error('片段未在原文中找到，请从原文复制真实片段。');p.fragmentStart=n;}for(const c of p.chapters)if(c.start<0||c.end>p.original.length||c.start>=c.end)throw Error('章节起止范围无效，请在解析预览中校正。');return t;}
function notify(t){message=t;const el=$('#ss-message');if(el)el.textContent=t;}
function progress(stage){if(stage>0&&!p.original.trim())throw Error('先输入灵感，或上传 / 粘贴已有内容。');if(stage>=2&&!p.story.trim())throw Error('先选择故事方向，或确认已有内容的处理范围。');if(stage>=3&&!p.story.trim())throw Error('故事稿不能为空。');if(stage>=4&&!p.analysisConfirmed&&!p.outline.length)throw Error('请先在剧情分析中核对并确认事实。');if(stage>=5&&!p.outline.length)throw Error('先整理至少一集大纲。');if(stage>=6&&!Object.keys(p.scripts).length)throw Error('先整理或编辑至少一集故事。');p.stage=stage;message='';rewriteOpen=false;save();render();}
function next(){if(p.stage===0){M.parse(p);if(p.origin==='idea'){p.directions=M.directions(p);p.stage=1;}else p.stage=1;return;}if(p.stage===1&&p.origin==='import'){validateRange();const w=M.processingWarning(p);if(w)throw Error(w);p.confirmed=true;M.process(p);p.stage=2;return;}if(p.stage===2){if(!p.story.trim())throw Error('请填写故事稿。');if(p.storyDraft)p.storyDraft.status='confirmed';if(!p.based.hasOwnProperty('analysis'))M.analyze(p);p.stage=3;return;}if(p.stage===3){p.analysisConfirmed=true;p.based.analysis=p.revisions.story;if(!p.outline.length)M.outline(p,2);p.stage=4;return;}if(p.stage===4){if(!p.outline.length)throw Error('请先整理分集大纲。');p.based.outline=p.revisions.analysis;p.stage=5;p.selectedEpisode=p.selectedEpisode||p.outline[0].id;message='';return;}if(p.stage===5){if(!Object.keys(p.scripts).length)throw Error('请先整理当前集故事。');p.stage=6;return;}if(p.stage===6){location.hash='#/app';}}
function download(kind){let a=Object.keys(p.scripts).length?M.asset(p):{...M.clone(p),type:'cimora-script-asset',assetId:p.savedAssetId||M.id('script-asset')};options.download(kind==='json'?M.exportJSON(a):M.exportText(a),p.title+(kind==='json'?'-故事工程.json':'-故事.txt'),kind==='json'?'application/json':'text/plain');}
function publish(){for(const c of p.characters){if(!c.name.trim())throw Error('请给每位人物填写姓名。');const names=[c.name,...c.aliases.split(/[、,，]/)].map(s=>s.trim()).filter(Boolean);if(p.characters.some(other=>other.id!==c.id&&[other.name,...other.aliases.split(/[、,，]/)].some(n=>names.includes(n.trim()))))throw Error('人物姓名或别名重复，请在剧情分析中合并身份后保存。');}let a=M.asset(p);p.savedAssetId=a.assetId;a.savedAssetId=a.assetId;const i=state.assets.findIndex(x=>x.assetId===a.assetId);if(i<0)state.assets.push(a);else state.assets[i]=a;message='故事资产已保存，原文与来源独立保留。';}
function bind(){
host.querySelectorAll('[data-import-field]').forEach(el=>el.oninput=()=>{p.importAnalysis[el.dataset.importField]=el.value;p.importAnalysis[el.dataset.importField+'Corrected']=true;const section=el.closest('section');if(el.dataset.importField==='genre'){const tags=section.querySelector('.ss-import-tags');tags.innerHTML=el.value.split(/[·、,，]/).filter(x=>x.trim()).map(x=>'<span>'+E(x.trim())+'</span>').join('')||'<span>暂无法判断</span>';}else section.querySelector('.ss-import-audience').textContent=el.value||'暂无法判断';save();});
host.querySelectorAll('[data-body-text]').forEach(el=>el.oninput=()=>{M.setBody(p,el.dataset.bodyText,el.value);const c=M.bodyCount(el.value,p.bodySettings?.language||'zh');host.querySelector('[data-body-count="'+el.dataset.bodyText+'"]').textContent=c.value+' '+c.unit;save();});
if($('#ss-focus-text'))$('#ss-focus-text').oninput=e=>focusText=e.target.value;
if($('#ss-body-request'))$('#ss-body-request').oninput=e=>{p.scripts[bodyRequest].requestDraft=e.target.value;save();};
for(const [selector,key]of [['#ss-body-preset','preset'],['#ss-body-language','language'],['#ss-body-target','target']])if($(selector))$(selector).onchange=e=>{p.bodySettings={preset:'standard',target:1200,language:'zh',...(p.bodySettings||{})};p.bodySettings[key]=key==='target'?Math.max(1,+e.target.value||1200):e.target.value;if(key==='preset'&&e.target.value!=='custom')p.bodySettings.target={short:800,standard:1200,detailed:1800}[e.target.value];save();render();};

host.querySelectorAll('[data-phase-select]').forEach(el=>el.onclick=e=>{e.preventDefault();p.selectedPhase=el.dataset.phaseSelect;p.outlineShowAll=false;save();render();});
host.querySelectorAll('[data-phase-direction]').forEach(el=>el.oninput=()=>{const g=M.stageGroups(p).find(g=>g.id===el.dataset.phaseDirection);p.outlinePhases??=[];let phase=p.outlinePhases.find(x=>x.id===g.id);if(!phase){phase={id:g.id,title:g.title};p.outlinePhases.push(phase);}phase.direction=el.value;M.touch(p,'outline');save();});

for(const [selector,key]of [['#ss-plan-mode','mode'],['#ss-plan-count','count'],['#ss-plan-minutes','minutes'],['#ss-plan-coverage','coverage']])if($(selector))$(selector).onchange=e=>{p.outlineSettings=M.outlineSettings(p);p.outlineSettings[key]=['count','minutes'].includes(key)?Math.max(1,Math.min(key==='count'?12:120,+e.target.value||1)):e.target.value;if(key==='mode')p.outlineSettings.count=Math.max(1,Math.min(12,Math.round(M.outlineRecommendation(p).count*({compact:.65,standard:1,expanded:1.5}[e.target.value]))));outlineProposal=null;save();render();};
if($('#ss-phase-direction'))$('#ss-phase-direction').oninput=e=>{const g=M.stageGroups(p).find(g=>g.id===p.selectedPhase)||M.stageGroups(p)[0];p.outlinePhases??=[];let phase=p.outlinePhases.find(x=>x.id===g.id);if(!phase){phase={id:g.id,title:g.title};p.outlinePhases.push(phase);}phase.direction=e.target.value;M.touch(p,'outline');save();};
if($('#ss-outline-request'))$('#ss-outline-request').oninput=e=>{p.outline.find(e=>e.id===episodeRequest).requestDraft=e.target.value;save();};

host.querySelectorAll('[data-character]').forEach(el=>{el.oninput=()=>{const c=activeCharacter();c[el.dataset.character]=el.value;if(!characterDraft){M.touch(p,'analysis');p.analysisConfirmed=false;save();}};if(el.tagName==='SELECT')el.onchange=el.oninput;});
if($('#ss-trait-input')){const el=$('#ss-trait-input');el.oninput=()=>traitDraft=el.value;el.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.isComposing){e.preventDefault();const t=el.value.trim();if(!t)return;const c=activeCharacter();c.personalityTags??=[];if(!c.personalityTags.includes(t))c.personalityTags.push(t);traitDraft='';if(!characterDraft){M.touch(p,'analysis');p.analysisConfirmed=false;save();}render();$('#ss-trait-input')?.focus();}};}

if($('#ss-work-request'))$('#ss-work-request').oninput=e=>{p.workAssistant??={};const a=p.workAssistant[workTab()]??={messages:[],draft:''};a.draft=e.target.value;save();};
if($('#ss-episode-count'))$('#ss-episode-count').oninput=e=>{p.plannedEpisodes=Math.max(1,Math.min(12,+e.target.value||2));save();};
if($('#ss-story-request'))$('#ss-story-request').oninput=e=>{p.storyRequest=e.target.value;save();};


host.querySelectorAll('[data-pref-search]').forEach(el=>{el.onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();const key=el.dataset.prefSearch,label=el.value.trim();if(!label)return;const preset=presets[key].find(x=>x[1]===label);M.preferenceToggle(p,prefStore(true),key,preset?.[0]||M.id('custom'),label);prefUI[key]='';save();const scroll=$('.ss-idea-chat')?.scrollTop;render();$('.ss-idea-chat').scrollTop=scroll;}};el.oninput=()=>{prefUI[el.dataset.prefSearch]=el.value;host.querySelectorAll('[data-pref-options="'+el.dataset.prefSearch+'"] [data-pref-option]').forEach(x=>x.hidden=!x.dataset.prefOption.includes(el.value));};});
host.querySelectorAll('[data-pref-legacy]').forEach(el=>el.oninput=()=>{const key=el.dataset.prefLegacy,v=M.preferenceState(p,prefStore(),key);v.legacy=el.value;v.value=[v.legacy,...v.tags.map(t=>t.label)].filter(Boolean).join('、');p.settings[key]=v.value;prefStore(true)[key]=v;save();});
const audience=$('#ss-pref-audience');if(audience&&audience.tagName==='SELECT')audience.onchange=()=>{prefUI.audienceCustom=audience.value==='custom';if(!prefUI.audienceCustom)p.settings.audience=({children:'儿童',teen:'青少年',adult:'成人'}[audience.value]||'');save();render();};

host.querySelectorAll('[data-plan]').forEach(el=>el.oninput=()=>{const d=M.ideaDesk(p);d.plans[d.selected][el.dataset.plan]=el.value;if(el.dataset.plan==='title'){p.title=el.value;$('#ss-projects').selectedOptions[0].textContent=p.title;}save();});
if($('#ss-idea-message'))$('#ss-idea-message').oninput=e=>{M.ideaDesk(p).draft=e.target.value;save();};
host.querySelectorAll('[data-p]').forEach(el=>{el.oninput=()=>{const path=el.dataset.p,keys=path.split('.');let o=p;for(const k of keys.slice(0,-1))o=o[k];if(path==='story'&&p.storyDraft?.status!=='modified'){const meta=M.clone(p.storyDraft||null);if(meta)delete meta.undo;p.storyDraft={kind:M.ideaStoryStatus(p).includes('结构稿')?'structure':'body',...(p.storyDraft||{}),status:'modified',undo:{story:p.story,meta}};}o[keys.at(-1)]=el.value;if(path==='story'){M.touch(p,'story');p.analysisConfirmed=false;const status=host.querySelector('.ss-body [role="status"]');if(p.origin==='idea'&&status)status.textContent=M.ideaStoryStatus(p);const undo=host.querySelector('[data-ss="story-undo"]');if(undo)undo.disabled=!p.storyDraft?.undo;}if(path.startsWith('analysis.')||/^(characters|facts|places|props)/.test(path)){M.touch(p,'analysis');p.analysisConfirmed=false;}if(path.startsWith('outline.')&&!path.endsWith('.state')&&!path.endsWith('.foreshadow'))M.touch(p,'outline');if(path==='original'){p.confirmed=false;if(p.origin==='import'){if(p.sourceAuthority)p.sourceNeedsReview=p.sourceBaseline!==p.original;const valid=p.importAnalysis?.sourceText===p.original;const go=host.querySelector('[data-ss="start-import"]');if(go)go.disabled=!valid;const status=$('#ss-import-valid');if(status&&!valid)status.textContent='原文已变化，请重新分析。';}}save();let warn=$('#ss-length-warning');if(warn)warn.textContent=M.processingWarning(p);if(path==='title'){$('#ss-projects').selectedOptions[0].textContent=p.title;const heading=$('.ss-heading h1');if(heading&&p.stage>=2)heading.textContent=p.title;}};if(el.tagName==='SELECT')el.onchange=()=>{el.oninput();if(['scope','contentType','processing','target'].includes(el.dataset.p))render();};});
host.querySelectorAll('[data-bound]').forEach(el=>el.onchange=()=>{p.chapters[+el.dataset.bound][el.dataset.edge]=Number(el.value);save();render();});host.querySelectorAll('[data-chapter]').forEach(el=>el.onchange=()=>{p.chapterIds=el.checked?[...new Set([...p.chapterIds,el.dataset.chapter])]:p.chapterIds.filter(x=>x!==el.dataset.chapter);save();render();});host.querySelectorAll('[data-scene-person]').forEach(el=>el.onchange=()=>{const s=p.scripts[p.selectedEpisode].scenes[p.selectedScene];s.characterIds=el.checked?[...new Set([...s.characterIds,el.dataset.scenePerson])]:s.characterIds.filter(x=>x!==el.dataset.scenePerson);save();});
$('#ss-projects').onchange=e=>{state.active=e.target.value;prefUI.audienceCustom=false;prefUI.active=null;storyReplace=false;useOpen=false;personId='';characterDraft=null;traitDraft='';bodySettingsOpen=false;bodyConfirm=null;bodyFocus=null;bodyRequest='';focusText='';bodyBatchConfirm=null;p=state.projects.find(x=>x.id===state.active);message='已切换故事工程';save();render();};if($('#ss-episode'))$('#ss-episode').onchange=e=>{p.selectedEpisode=e.target.value;p.selectedScene=0;save();render();};
if($('#ss-upload'))$('#ss-upload').onchange=async e=>{const file=e.target.files[0],target=p;if(!file)return;busy=true;notify('正在本机读取文件，请稍候…');host.querySelectorAll('[data-ss="next"]').forEach(b=>b.disabled=true);try{const result=await ScriptImport.read(file);if(!alive)return;const candidate=M.clone(target);candidate.original=result.text;candidate.sourceName=file.name;candidate.importNote=result.note;M.analyzeImport(candidate);candidate.stage=1;Object.assign(target,candidate);if(p===target){notify('已完整读取，请核对素材分析概览。');save();render();}}catch(err){if(alive)notify(err.message);}finally{busy=false;if(alive)host.querySelectorAll('[data-ss="next"]').forEach(b=>b.disabled=false);}};
host.querySelectorAll('[data-ss]').forEach(b=>b.onclick=async event=>{event?.preventDefault();if(busy)return;try{const action=b.dataset.ss,ep=b.dataset.id,prefScroll=action.startsWith('pref-')?$('.ss-idea-chat')?.scrollTop:null;if(action.startsWith('body-')){handleBody(action,ep);if(action==='body-jump'){save();return;}}else if(action.startsWith('plan-')&&action!=='plan-sample'){handleOutline(action,ep);}else if(action==='people-complete'){const count=M.completeCharacters(p);message=count?'已补充缺失资料，手填内容保持不变。':'角色资料已齐全，没有改写。';}else if(action==='people-undo'){M.undoCharacters(p);message='已撤回可安全恢复的补全，后续手改与引用保留。';}else if(action==='people-add-open'){characterDraft={name:'',role:'',age:'',gender:'',personality:'',personalityTags:[],background:''};traitDraft='';message='';}else if(action==='people-create-cancel'){characterDraft=null;traitDraft='';message='';}else if(action==='people-create-submit'){const name=characterDraft.name.trim();if(!name)throw Error('请填写角色姓名。');if(p.characters.some(c=>[c.name,...(c.aliases||'').split(/[、,，]/)].includes(name)))throw Error('该姓名已存在，请选择已有角色。');const c=M.addCharacter(p,name);Object.assign(c,M.clone(characterDraft),{name});personId=c.id;p.selectedPersonId=c.id;characterDraft=null;traitDraft='';M.touch(p,'analysis');p.analysisConfirmed=false;message='角色已创建。';}else if(action==='trait-remove'){const c=activeCharacter();c.personalityTags.splice(+b.dataset.index,1);if(!characterDraft){M.touch(p,'analysis');p.analysisConfirmed=false;}} else if(action==='full-example'){if(p.original.trim()||p.story.trim()||p.creationRequirements||p.importRequest?.trim()){if(!save())throw Error('当前输入未能保存，请先保留原稿。');}const fresh=ScriptFullExample.build(M);p=fresh;useOpen=false;storyReplace=false;personId='';characterDraft=null;traitDraft='';outlineProposal=null;outlineConfirm=null;bodyFocus=null;bodyConfirm=null;bodyRequest='';message='已另建“全流程创作体验示例”：人工完整创作的10集爱情故事，未调用模型，未发布资产；原项目保留。';}else if(action==='plan-sample'){const fresh=M.create();fresh.original=ScriptSample.seed;fresh.title='磁带里的明天 · 策划样例';fresh.sourceName='完整预制策划样例';p=fresh;M.ideaStart(p);}else if(action==='idea-restart'){restartConfirm=true;}else if(action==='idea-restart-cancel'){restartConfirm=false;}else if(action==='idea-restart-confirm'){p.archivedIdeaDesks??=[];p.archivedIdeaDesks.push(M.clone(p.ideaDesk));delete p.ideaDesk;try{M.ideaStart(p);restartConfirm=false;}catch(error){p.ideaDesk=p.archivedIdeaDesks.pop();throw error;}}else if(action==='use-open'){useOpen=true;}else if(action==='use-close'){useOpen=false;}else if(action.startsWith('work-')&&!['work-refine','work-undo'].includes(action)){const stages={overview:2,people:3,outline:4,body:5};const target=stages[action.slice(5)];if(target){if(!p.story.trim())throw Error('先填写故事梗概。');if(target===3&&!p.characters.length)M.ensureCharacters(p);p.stage=target;useOpen=false;}}else if(action==='person-select'){characterDraft=null;traitDraft='';personId=ep;p.selectedPersonId=ep;}else if(action==='import-sample'){if(p.original.trim()||p.importRequest?.trim()||p.story.trim()||p.outline.length){save();const fresh=M.create();fresh.origin='import';p=fresh;message='已另建示范项目，原输入保留在项目列表。';}p.origin='import';p.original=ScriptSample.importDemo.text;p.title=ScriptSample.importDemo.title+' · 示范';p.sourceName='自写完整示范 · 桥另一边的种子';M.analyzeImport(p);p.stage=1;}else if(action==='start-parse'){M.analyzeImport(p);p.stage=1;message='';}else if(action==='start-import'){M.enterImport(p);message=p.sourceNeedsReview?'原文已变化，现有手改与下游保留，来源待核对。':'';}else if(action==='work-refine'||action==='work-undo'){p.workAssistant??={};const a=p.workAssistant[workTab()]??={draft:'',messages:[]};if(action==='work-refine'){if(!a.draft.trim())throw Error('先写下修改要求。');if(workTab()==='overview'&&/类型|题材|风格|读者|受众|背景|设定|世界观|核心.{0,3}(规则|设定)|genre|style|audience|world.?rule/i.test(a.draft)){notify('这些属于前面策划；此处只完善梗概，相关设定保持不变。');return;}a.messages.push(a.draft.trim());a.draft='';message='修改要求已记录，待融合；现有内容保留。';}else{a.messages.pop();message='已撤回上一条要求，手改内容保持原样。';}}else if(action==='pref-open'){prefUI.active=prefUI.active===b.dataset.key?null:b.dataset.key;}else if(action==='pref-close'){prefUI.active=null;}else if(action==='pref-toggle'){M.preferenceToggle(p,prefStore(true),b.dataset.key,b.dataset.token,b.dataset.label);}else if(action==='pref-custom'){const key=b.dataset.key,label=prefUI[key].trim();if(!label)return;const preset=presets[key].find(x=>x[1]===label);M.preferenceToggle(p,prefStore(true),key,preset?.[0]||M.id('custom'),label);prefUI[key]='';}else if(action==='pref-more'){prefUI.more=!prefUI.more;}else if(action==='pref-core'){M.preferenceAppend(p,b.dataset.label);}else if(action==='idea-start'){M.ideaStart(p);message='';}else if(action==='idea-choose'){M.ideaChoose(p,+b.dataset.index);}else if(action==='idea-refine'){M.ideaRefine(p);}else if(action==='idea-undo'){M.ideaUndo(p);}else if(action==='idea-adopt'||action==='story-replace'){if(p.ideaDesk&&!p.ideaDesk.plans[p.ideaDesk.selected]&&p.ideaDesk.plans.length)M.ideaChoose(p,0);if(p.story.trim()&&action!=='story-replace'){storyReplace=true;render();return;}busy=true;notify('生成演示中…');await new Promise(resolve=>setTimeout(resolve,120));try{M.ideaAdopt(p,action==='story-replace');storyReplace=false;message='演示完成：当前为结构稿，待继续写成正文。';}finally{busy=false;}}else if(action==='story-cancel'){storyReplace=false;}else if(action==='story-refine'){M.ideaStoryRefine(p,p.storyRequest||'');p.storyRequest='';message='修改要求已保存，待融合。';}else if(action==='story-undo'){M.ideaStoryUndo(p);message='已恢复上一版，其他下游内容保留。';}else if(action==='step'){progress(+b.dataset.index);return;}else if(action==='back'){progress(M.previousStage(p));return;}else if(action==='next')next();else if(action.startsWith('origin-')){const origin=action.slice(7);if(origin!==p.origin){p.startDrafts??={};p.startDrafts[p.origin]=p.original;p.original=p.startDrafts[origin]||'';p.origin=origin;p.stage=0;}}else if(action==='tag'){const tags=p.settings.style.split('、').filter(Boolean);p.settings.style=tags.includes(b.dataset.tag)?tags.filter(x=>x!==b.dataset.tag).join('、'):[...tags,b.dataset.tag].join('、');}else if(action.startsWith('sample-')){if(p.original.trim()){p=M.create();state.projects.push(p);message='已另建样例工程，原稿保留在工程列表。';}const kind=action.slice(7);p.origin=kind==='idea'?'idea':'import';p.original=kind==='idea'?ScriptSample.seed:kind==='novel'?ScriptSample.novel:ScriptSample.screenplay;p.title='末班车录音'+(kind==='novel'?' · 小说':kind==='script'?' · 现成分场内容':'');p.sourceName='内置完整样例';M.parse(p);}else if(action==='direction'){M.selectDirection(p,+b.dataset.index);}else if(action==='process'){if(p.processConfirm!==p.revisions.story){p.processConfirm=p.revisions.story;notify('再次点击“按所选方式整理”将替换故事稿；原文与下游手改保留。');save();return;}M.process(p);delete p.processConfirm;message=p.processingNote;}else if(action==='direct'){validateRange();if(M.count(M.rangeText(p))>4000)throw Error('现成分场内容范围超过约4000字建议，请选某场 / 片段逐次整理，原文不会截断。');if(p.outline.length)throw Error('本工程已有规划，请另建工程导入现成分场内容，避免覆盖。');M.directScript(p);p.analysisConfirmed=true;}else if(action==='add-person'){const name=$('#ss-new-person').value.trim();if(!name)throw Error('请填写人物姓名或别名。');let n=p.characters.length,c=M.addCharacter(p,name,$('#ss-new-alias').value);personId=c.id;p.selectedPersonId=c.id;personCreate=false;M.touch(p,'analysis');message=n===p.characters.length?'已定位现有人物：'+c.name+'；没有重复建人。':'已添加人物，身份可继续填写。';}else if(action==='add-place'||action==='add-prop'){p[action==='add-place'?'places':'props'].push({id:M.id(),name:'',role:''});M.touch(p,'analysis');}else if(action==='confirm-analysis'){p.analysisConfirmed=true;p.based.analysis=p.revisions.story;message='事实已确认。';}else if(action==='outline'){M.outline(p,$('#ss-episode-count')?.value||p.plannedEpisodes||2);}else if(action==='confirm-outline'){p.based.outline=p.revisions.analysis;message='已核对大纲；后续故事保持原样。';}else if(action==='split'){if(p.outline.length>=12)throw Error('本轮最多规划12集，请逐集创作。');M.split(p,ep);}else if(action==='merge'){M.merge(p,ep);}else if(action==='move-up'||action==='move-down')M.move(p,ep,action==='move-up'?-1:1);else if(action==='write')M.writeEpisode(p,p.selectedEpisode);else if(action==='scene'){p.selectedScene=+b.dataset.index;rewriteOpen=false;}else if(action==='add-scene'){const s=p.scripts[p.selectedEpisode];s.scenes.push({id:M.id('scene'),title:'场'+(s.scenes.length+1),time:'',place:'',characterIds:p.characters.map(c=>c.id),action:'',dialogue:'',mind:'',source:''});p.selectedScene=s.scenes.length-1;}else if(action==='keep-script'){p.scripts[p.selectedEpisode].basedOutline=p.revisions.outline;p.based.outline=p.revisions.analysis;p.based.analysis=p.revisions.story;message='已核对，沿用当前手改内容。';}else if(action==='rewrite')rewriteOpen=true;else if(action==='cancel-rewrite')rewriteOpen=false;else if(action==='apply-rewrite'){p.scripts[p.selectedEpisode].scenes[p.selectedScene].action=$('#ss-rewrite').value;rewriteOpen=false;message='仅替换当前场动作，其他场保留。';}else if(action==='publish')publish();else if(action==='export-json'){download('json');return;}else if(action==='export-text'){download('txt');return;}else if(action==='comic'||action==='video'){const a=state.assets.find(a=>a.assetId===p.savedAssetId);if(!a)throw Error('先保存故事资产。');save();options.handoff(a,$('#ss-handoff-episode').value,action);return;}save();if(alive&&location.hash.startsWith('#/app/script')){render();if(['idea-refine','idea-undo'].includes(action)&&$('.ss-idea-messages'))$('.ss-idea-messages').scrollTop=$('.ss-idea-messages').scrollHeight;if(prefScroll!==null&&$('.ss-idea-chat'))$('.ss-idea-chat').scrollTop=prefScroll;}}catch(e){notify(e.message);}});
}
render();return {destroy(){alive=false;},project:()=>p};
};
